/**
 * A handle to one engine. Every call but `recovery` is `async`, and every call throws [`CraftError`].
 * A call reaches the engine as it is first polled, which the foreign caller does as it makes the call,
 * and awaits the answer the engine thread sends it, so the engine runs calls in the order they were
 * made and no thread blocks for an answer, bar `shut_down`'s wait for the engine thread to stop, which
 * a thread of its own makes.
 */
public interface EngineInterface {
    
    /**
     * Give up the preview surface the app attached, if one is: after this the `present` is the same empty
     * answer it was before the attach, and detaching nothing answers `Ok`. Like every call it waits its
     * turn, so ending a preview waits behind a running export.
     */
    suspend fun `detachPreview`()
    
    /**
     * Render one frame as `format`. The bytes are copied as they cross, and a frame the boundary
     * cannot carry is refused (see [`crate::MAX_FRAME_BYTES`]).
     */
    suspend fun `frame`(`params`: kotlin.String, `format`: PixelFormat): FrameBytes
    
    /**
     * Answer whether the engine holds a preview surface: from an `attach` of the app's layer or
     * window until `detach_preview` gives it up, or the GPU goes with it — suspended for the
     * background, or lost. A preview call skips its attach only while this answers yes and the
     * surface held is its own, so one question, asked of the engine that holds the answer, serves
     * both bindings; neither keeps a copy of the fact of its own.
     */
    suspend fun `hasPreviewSurface`(): kotlin.Boolean
    
    /**
     * Answer one line of the app's MCP transport with the one line it replies with, or `None` for a
     * line that needs no reply. A closed engine and a caught panic throw, as `request` does.
     */
    suspend fun `mcp`(`line`: kotlin.String): kotlin.String?
    
    /**
     * Draw one frame on the preview surface the app attached, and show it: the parameters are the app's
     * `present` call's, and the frame waits its turn behind a running export as every call does. With
     * nothing attached it throws `Gpu` with `no surface`; a surface lost or changed mid-preview throws
     * `Gpu` too — the session is kept either way, and the next `present` draws once the surface answers
     * again or a new one is attached.
     */
    suspend fun `present`(`params`: kotlin.String)
    
    /**
