sealed class CraftException: kotlin.Exception() {
    
    class InvalidParams(
        
        val `detail`: kotlin.String
        ) : CraftException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class CommandFailed(
        
        val `command`: kotlin.String, 
        
        val `detail`: kotlin.String, 
        
        val `step`: kotlin.UInt?
        ) : CraftException() {
        override val message
            get() = "command=${ `command` }, detail=${ `detail` }, step=${ `step` }"
    }
    
    class NotFound(
        
        val `detail`: kotlin.String
        ) : CraftException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Unsupported(
        
        val `detail`: kotlin.String
        ) : CraftException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Cancelled(
        ) : CraftException() {
        override val message
            get() = ""
    }
    
    class Io(
        
        val `detail`: kotlin.String
        ) : CraftException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Gpu(
        
        val `detail`: kotlin.String
        ) : CraftException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Internal(
        
        val `detail`: kotlin.String
        ) : CraftException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CraftException> {
        override fun lift(error_buf: RustBuffer.ByValue): CraftException = FfiConverterTypeCraftError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCraftError : FfiConverterRustBuffer<CraftException> {
    override fun read(buf: ByteBuffer): CraftException {
        

        return when(buf.getInt()) {
            1 -> CraftException.InvalidParams(
                FfiConverterString.read(buf),
                )
            2 -> CraftException.CommandFailed(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalUInt.read(buf),
                )
            3 -> CraftException.NotFound(
                FfiConverterString.read(buf),
                )
            4 -> CraftException.Unsupported(
                FfiConverterString.read(buf),
                )
            5 -> CraftException.Cancelled()
            6 -> CraftException.Io(
                FfiConverterString.read(buf),
                )
            7 -> CraftException.Gpu(
                FfiConverterString.read(buf),
                )
            8 -> CraftException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CraftException): ULong {
        return when(value) {
            is CraftException.InvalidParams -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CraftException.CommandFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`command`)
                + FfiConverterString.allocationSize(value.`detail`)
                + FfiConverterOptionalUInt.allocationSize(value.`step`)
            )
            is CraftException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CraftException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CraftException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CraftException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CraftException.Gpu -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CraftException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: CraftException, buf: ByteBuffer) {
        when(value) {
            is CraftException.InvalidParams -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CraftException.CommandFailed -> {
                buf.putInt(2)
                FfiConverterString.write(value.`command`, buf)
                FfiConverterString.write(value.`detail`, buf)
                FfiConverterOptionalUInt.write(value.`step`, buf)
                Unit
            }
            is CraftException.NotFound -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CraftException.Unsupported -> {
                buf.putInt(4)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CraftException.Cancelled -> {
                buf.putInt(5)
                Unit
            }
            is CraftException.Io -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CraftException.Gpu -> {
                buf.putInt(7)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CraftException.Internal -> {
                buf.putInt(8)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




